public enum CPFont {
    public static let display = "PlusJakartaSans"  // register PlusJakartaSans-*.ttf in Info.plist UIAppFonts
    public static let text = "Inter"
    public static let mono = "JetBrainsMono"
}

public struct CPTextStyle {
    public let font: Font
    public let size: CGFloat
    public let lineHeight: CGFloat
    public let tracking: CGFloat
    public let uppercase: Bool
    /// SwiftUI lineSpacing is extra space between lines, not the full line box.
    public var lineSpacing: CGFloat { lineHeight - size * 1.2 }
}

public enum CPType {
    public static let displayLg = CPTextStyle(font: Font.custom(CPFont.display, size: 40, relativeTo: .largeTitle).weight(.heavy), size: 40, lineHeight: 48, tracking: -0.8, uppercase: false)
    public static let display = CPTextStyle(font: Font.custom(CPFont.display, size: 32, relativeTo: .largeTitle).weight(.heavy), size: 32, lineHeight: 40, tracking: -0.64, uppercase: false)
    public static let h1 = CPTextStyle(font: Font.custom(CPFont.display, size: 28, relativeTo: .largeTitle).weight(.bold), size: 28, lineHeight: 36, tracking: -0.42, uppercase: false)
    public static let h2 = CPTextStyle(font: Font.custom(CPFont.display, size: 24, relativeTo: .title2).weight(.bold), size: 24, lineHeight: 32, tracking: -0.24, uppercase: false)
    public static let h3 = CPTextStyle(font: Font.custom(CPFont.display, size: 20, relativeTo: .title2).weight(.bold), size: 20, lineHeight: 28, tracking: -0.1, uppercase: false)
    public static let title = CPTextStyle(font: Font.custom(CPFont.text, size: 17, relativeTo: .headline).weight(.semibold), size: 17, lineHeight: 24, tracking: -0.17, uppercase: false)
    public static let bodyLg = CPTextStyle(font: Font.custom(CPFont.text, size: 16, relativeTo: .body).weight(.regular), size: 16, lineHeight: 24, tracking: -0.08, uppercase: false)
    public static let body = CPTextStyle(font: Font.custom(CPFont.text, size: 14, relativeTo: .body).weight(.regular), size: 14, lineHeight: 20, tracking: 0, uppercase: false)
    public static let bodyStrong = CPTextStyle(font: Font.custom(CPFont.text, size: 14, relativeTo: .body).weight(.semibold), size: 14, lineHeight: 20, tracking: 0, uppercase: false)
    public static let label = CPTextStyle(font: Font.custom(CPFont.text, size: 15, relativeTo: .body).weight(.semibold), size: 15, lineHeight: 20, tracking: -0.07, uppercase: false)
    public static let labelSm = CPTextStyle(font: Font.custom(CPFont.text, size: 13, relativeTo: .caption).weight(.semibold), size: 13, lineHeight: 16, tracking: 0, uppercase: false)
    public static let caption = CPTextStyle(font: Font.custom(CPFont.text, size: 12, relativeTo: .caption).weight(.medium), size: 12, lineHeight: 16, tracking: 0.06, uppercase: false)
    public static let overline = CPTextStyle(font: Font.custom(CPFont.text, size: 11, relativeTo: .caption2).weight(.semibold), size: 11, lineHeight: 16, tracking: 0.66, uppercase: true)
    public static let amountXl = CPTextStyle(font: Font.custom(CPFont.display, size: 40, relativeTo: .largeTitle).weight(.heavy).monospacedDigit(), size: 40, lineHeight: 48, tracking: -0.8, uppercase: false)
    public static let amount = CPTextStyle(font: Font.custom(CPFont.display, size: 24, relativeTo: .title2).weight(.bold).monospacedDigit(), size: 24, lineHeight: 32, tracking: -0.24, uppercase: false)
    public static let code = CPTextStyle(font: Font.custom(CPFont.mono, size: 13, relativeTo: .caption).weight(.regular), size: 13, lineHeight: 20, tracking: 0, uppercase: false)
}

public extension View {
    func cpText(_ s: CPTextStyle) -> some View {
        font(s.font).tracking(s.tracking).lineSpacing(max(0, s.lineSpacing)).textCase(s.uppercase ? .uppercase : nil)
    }
}

