public enum CPMotion {
    public static let instant: Double = 0.1
    public static let fast: Double = 0.15
    public static let base: Double = 0.2
    public static let moderate: Double = 0.3
    public static let slow: Double = 0.45
    public static let deliberate: Double = 0.6
    public static let shimmer: Double = 1.4
    public static func standard(_ duration: Double = base) -> Animation { .timingCurve(0.2, 0, 0, 1, duration: duration) }
    public static func enter(_ duration: Double = base) -> Animation { .timingCurve(0, 0, 0, 1, duration: duration) }
    public static func exit(_ duration: Double = base) -> Animation { .timingCurve(0.3, 0, 1, 1, duration: duration) }
    public static func emphasized(_ duration: Double = base) -> Animation { .timingCurve(0.3, 0, 0, 1, duration: duration) }
    public static func linear(_ duration: Double = base) -> Animation { .timingCurve(0, 0, 1, 1, duration: duration) }
    public static let snappySpring: Animation = .spring(response: 0.3, dampingFraction: 0.86)
    public static let smoothSpring: Animation = .spring(response: 0.45, dampingFraction: 1)
    public static let bouncySpring: Animation = .spring(response: 0.5, dampingFraction: 0.7)
    public static let pressedScale: CGFloat = 0.97
    public static let disabledOpacity: Double = 0.4
}

