}

public extension LinearGradient {
    static let cpBrand = LinearGradient(stops: [.init(color: Color(cpHex: 0x381987), location: 0), .init(color: Color(cpHex: 0x01AAA5), location: 1)], startPoint: .leading, endPoint: .trailing)
    /// The product's logo gradient (left -> right).
    static func cp(_ product: CPProduct) -> LinearGradient {
        switch product {
        case .consumer: return LinearGradient(colors: [Color(cpHex: 0x381987), Color(cpHex: 0x01AAA5)], startPoint: .leading, endPoint: .trailing)
        case .seller: return LinearGradient(colors: [Color(cpHex: 0xF65F4F), Color(cpHex: 0xFDA73B)], startPoint: .leading, endPoint: .trailing)
        case .delivery: return LinearGradient(colors: [Color(cpHex: 0x750C6F), Color(cpHex: 0xED0066)], startPoint: .leading, endPoint: .trailing)
        case .console: return LinearGradient(colors: [Color(cpHex: 0x3C2566), Color(cpHex: 0x9478CB)], startPoint: .leading, endPoint: .trailing)
        case .events: return LinearGradient(colors: [Color(cpHex: 0x5F3A9F), Color(cpHex: 0x3966E6)], startPoint: .leading, endPoint: .trailing)
        case .kampus: return LinearGradient(colors: [Color(cpHex: 0x2450CC), Color(cpHex: 0x38BDF8)], startPoint: .leading, endPoint: .trailing)
        case .menu: return LinearGradient(colors: [Color(cpHex: 0xE1517D), Color(cpHex: 0xED7325)], startPoint: .leading, endPoint: .trailing)
        }
    }
}

public extension Color {
    init(cpHex: UInt32, alpha: Double = 1) {
        self.init(.sRGB, red: Double((cpHex >> 16) & 0xFF) / 255, green: Double((cpHex >> 8) & 0xFF) / 255,
                  blue: Double(cpHex & 0xFF) / 255, opacity: alpha)
    }
}
